insert into yh_user_bloodpressure (U_Bloodpressure_Id, Sbp, Dbp, 
  Entry_Time, Is_Del, E_User_Id, 
  xinlv, test_hj, type
  )
values (#{uBloodpressureId,jdbcType=INTEGER}, #{sbp,jdbcType=INTEGER}, #{dbp,jdbcType=INTEGER}, 
