  )

mapper.select:
select yhb.Sbp,yhb.Dbp,yhb.test_hj,yhb.Entry_Time from yh_user_reginfo as reg inner join yh_user_bloodpressure yhb on reg.user_code = yhb.E_User_Id and Is_Del = 2 where reg.user_code=#{ userCode,jdbcType=INTEGER}
and test_hj = #{testHj,jdbcType=VARCHAR}
order by Entry_Time
